using AutoMapper; using MediatR; using SMIS.Application.Common.Response; using SMIS.Application.DTO.ProductUnits; using SMIS.Application.Identity.IServices; using SMIS.Application.Repositories.Base; using SMIS.Application.Repositories.Products; using SMIS.Application.Repositories.ProductUnits; using SMIS.Domain.Entities; using SMIS.Domain.Services;
namespace SMIS.Application.Features.ProductUnits.Commands;
public record ProductUnitSyncCreateCommand(ProductUnitSyncCreateDto Dto) : IRequest<Result<ProductUnitDto>>;
public record ProductUnitSyncUpdateCommand(string Id, ProductUnitSyncUpdateDto Dto) : IRequest<Result<ProductUnitDto>>;
public record ProductUnitSyncDeleteCommand(string Id, ProductUnitSyncDeleteDto Dto) : IRequest<Result<ProductUnitDto>>;
internal sealed class ProductUnitSyncCreateCommandHandler : IRequestHandler<ProductUnitSyncCreateCommand, Result<ProductUnitDto>>
{ private readonly IProductUnitRepository _repository; private readonly IProductRepository _products; private readonly IUnitOfWork _uow; private readonly ICurrentUser _user; private readonly IMapper _mapper; public ProductUnitSyncCreateCommandHandler(IProductUnitRepository repository,IProductRepository products,IUnitOfWork uow,ICurrentUser user,IMapper mapper)=>(_repository,_products,_uow,_user,_mapper)=(repository,products,uow,user,mapper); public async Task<Result<ProductUnitDto>> Handle(ProductUnitSyncCreateCommand r,CancellationToken ct){var id=ProductUnitSyncRules.Id(r.Dto.Id);if(!ProductUnitSyncRules.User(r.Dto.ClientCreatedBy,_user)||!ProductUnitSyncRules.User(r.Dto.ClientModifiedBy,_user))return ProductUnitSyncRules.InvalidUser();var value=await _repository.GetByIdIncludingDeletedAsync(id,ct);var modified=DateTimeService.NormalizeUtc(r.Dto.ClientModifiedDate);if(value is not null){if(!await ProductUnitSyncRules.Access(value.ProductId,_products,_user,ct))return ProductUnitSyncRules.Forbidden();if(modified<=value.GetConflictModifiedUtc())return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));ProductUnitSyncRules.Apply(value,r.Dto);value.SetClientCreationMetadata(r.Dto.ClientCreatedDate,r.Dto.ClientCreatedBy);value.SetClientModificationMetadata(modified,r.Dto.ClientModifiedBy);value.Restore();await _uow.SaveChanges(ct);return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));}if(!await ProductUnitSyncRules.Access(r.Dto.ProductId,_products,_user,ct))return ProductUnitSyncRules.Forbidden();value=ProductUnit.Create(r.Dto.ProductId,r.Dto.UnitOfMeasureId,r.Dto.ConversionFactor);value.Id=id;value.SetClientCreationMetadata(r.Dto.ClientCreatedDate,r.Dto.ClientCreatedBy);value.SetClientModificationMetadata(modified,r.Dto.ClientModifiedBy);await _repository.AddAsync(value);await _uow.SaveChanges(ct);return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));} }
internal sealed class ProductUnitSyncUpdateCommandHandler : IRequestHandler<ProductUnitSyncUpdateCommand, Result<ProductUnitDto>>
{ private readonly IProductUnitRepository _repository; private readonly IProductRepository _products; private readonly IUnitOfWork _uow; private readonly ICurrentUser _user; private readonly IMapper _mapper; public ProductUnitSyncUpdateCommandHandler(IProductUnitRepository repository,IProductRepository products,IUnitOfWork uow,ICurrentUser user,IMapper mapper)=>(_repository,_products,_uow,_user,_mapper)=(repository,products,uow,user,mapper); public async Task<Result<ProductUnitDto>> Handle(ProductUnitSyncUpdateCommand r,CancellationToken ct){if(!ProductUnitSyncRules.User(r.Dto.ClientModifiedBy,_user))return ProductUnitSyncRules.InvalidUser();var value=await _repository.GetByIdIncludingDeletedAsync(ProductUnitSyncRules.Id(r.Id),ct);if(value is null)return Result<ProductUnitDto>.NotFoundResult(r.Id);if(!await ProductUnitSyncRules.Access(value.ProductId,_products,_user,ct)||!await ProductUnitSyncRules.Access(r.Dto.ProductId,_products,_user,ct))return ProductUnitSyncRules.Forbidden();var modified=DateTimeService.NormalizeUtc(r.Dto.ClientModifiedDate);if(modified<=value.GetConflictModifiedUtc())return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));ProductUnitSyncRules.Apply(value,r.Dto);value.SetClientModificationMetadata(modified,r.Dto.ClientModifiedBy);value.Restore();await _uow.SaveChanges(ct);return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));} }
internal sealed class ProductUnitSyncDeleteCommandHandler : IRequestHandler<ProductUnitSyncDeleteCommand, Result<ProductUnitDto>>
{ private readonly IProductUnitRepository _repository; private readonly IProductRepository _products; private readonly IUnitOfWork _uow; private readonly ICurrentUser _user; private readonly IMapper _mapper; public ProductUnitSyncDeleteCommandHandler(IProductUnitRepository repository,IProductRepository products,IUnitOfWork uow,ICurrentUser user,IMapper mapper)=>(_repository,_products,_uow,_user,_mapper)=(repository,products,uow,user,mapper); public async Task<Result<ProductUnitDto>> Handle(ProductUnitSyncDeleteCommand r,CancellationToken ct){if(!ProductUnitSyncRules.User(r.Dto.ClientModifiedBy,_user))return ProductUnitSyncRules.InvalidUser();var value=await _repository.GetByIdIncludingDeletedAsync(ProductUnitSyncRules.Id(r.Id),ct);if(value is null)return Result<ProductUnitDto>.NotFoundResult(r.Id);if(!await ProductUnitSyncRules.Access(value.ProductId,_products,_user,ct))return ProductUnitSyncRules.Forbidden();var modified=DateTimeService.NormalizeUtc(r.Dto.ClientModifiedDate);if(modified<=value.GetConflictModifiedUtc())return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));value.SetClientModificationMetadata(modified,r.Dto.ClientModifiedBy);await _repository.RemoveAsync(value);await _uow.SaveChanges(ct);return Result<ProductUnitDto>.SuccessResult(_mapper.Map<ProductUnitDto>(value));} }
internal static class ProductUnitSyncRules { public static string Id(string value)=>Guid.Parse(value).ToString("D"); public static bool User(string? value,ICurrentUser user)=>string.IsNullOrWhiteSpace(value)||string.Equals(value.Trim(),user.GetId(),StringComparison.Ordinal); public static async Task<bool> Access(string productId,IProductRepository products,ICurrentUser user,CancellationToken ct){var product=await products.GetByIdAsync(productId);return product is not null&&(user.IsSuperAdmin()||product.ShopId==user.GetShopId());} public static void Apply(ProductUnit value,ProductUnitSyncUpdateDto dto){value.SetProductId(dto.ProductId);value.SetUnitOfMeasureId(dto.UnitOfMeasureId);value.SetConversionFactor(dto.ConversionFactor);} public static Result<ProductUnitDto> InvalidUser()=>Result<ProductUnitDto>.FailureResult("InvalidClientUser","Client user metadata must match the authenticated user.");public static Result<ProductUnitDto> Forbidden()=>Result<ProductUnitDto>.FailureResult("Forbidden","You can only synchronize product units from your own shop."); }
